SELECT i.codigo, i.tipo, i.condominio_nome, i.bairro, i.sol, i.area_util, i.quartos, i.suites, i.vagas, i.vagas_cobertas, i.mobilia, i.valor_venda, i.valor_aluguel, i.taxa_condominio, i.disponivel, i.bloqueado, i.e_parceiro, i.extras->>'incluso no aluguel' AS incluso_aluguel, (SELECT count(*) FROM imovel_fotos f WHERE f.codigo = i.codigo) AS qtd_fotos FROM imoveis i WHERE i.codigo = $1;
